import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { createCreditNote } from '../src/credits.js';

test('createCreditNote creates a credit note for issued invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const r = createCreditNote(issued, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-0001');
  assert.equal(r.value.invoiceNumber, issued.number);
  assert.equal(r.value.customerId, 'C-003');
  assert.equal(r.value.amount, 5000);
  assert.equal(r.value.reason, 'Discount');
  assert.equal(r.value.date, '2026-10-08');
});

test('createCreditNote rejects draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const r = createCreditNote(invoice, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.deepEqual(r, { ok: false, error: 'NOT_ISSUED' });
});

test('createCreditNote accepts partially_paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const withPayment = recordPayment(issued, { amount: 10000, date: '2026-10-08' }).value;

  const r = createCreditNote(withPayment, { amount: 5000, reason: 'Discount', date: '2026-10-09' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-0001');
});

test('createCreditNote accepts paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const total = invoiceTotals(issued).value.total;
  const paid = recordPayment(issued, { amount: total, date: '2026-10-08' }).value;

  const r = createCreditNote(paid, { amount: 5000, reason: 'Discount', date: '2026-10-09' }, []);
  assert.equal(r.ok, true);
});

test('createCreditNote rejects non-integer amount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const r = createCreditNote(issued, { amount: 5000.5, reason: 'Discount', date: '2026-10-08' }, []);
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote rejects zero amount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const r = createCreditNote(issued, { amount: 0, reason: 'Discount', date: '2026-10-08' }, []);
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote rejects negative amount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const r = createCreditNote(issued, { amount: -5000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote rejects credit amount exceeding invoice total', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const total = invoiceTotals(issued).value.total;

  const r = createCreditNote(issued, { amount: total + 1, reason: 'Discount', date: '2026-10-08' }, []);
  assert.deepEqual(r, { ok: false, error: 'CREDIT_TOO_HIGH' });
});

test('createCreditNote accepts credit amount equal to invoice total', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const total = invoiceTotals(issued).value.total;

  const r = createCreditNote(issued, { amount: total, reason: 'Full Refund', date: '2026-10-08' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.amount, total);
});

test('createCreditNote numbers start from 1 for new year', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const r = createCreditNote(issued, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-0001');
});

test('createCreditNote increments counter', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const r1 = createCreditNote(issued, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(r1.ok, true);
  assert.equal(r1.value.number, 'CN-2026-0001');

  const r2 = createCreditNote(issued, { amount: 3000, reason: 'Discount', date: '2026-10-09' }, [r1.value.number]);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'CN-2026-0002');
});

test('createCreditNote has separate counter from invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, ['INV-2026-0001', 'INV-2026-0002']).value;

  const r = createCreditNote(issued, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, ['INV-2026-0001', 'INV-2026-0002']);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-0001');
});

test('createCreditNote with mixed existing numbers', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, ['INV-2026-0001']).value;

  const existing = ['INV-2026-0001', 'CN-2026-0001', 'CN-2026-0002'];
  const r = createCreditNote(issued, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, existing);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-0003');
});

test('createCreditNote with different years', () => {
  const invoice1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(invoice1, []).value;

  const invoice2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued2 = issueInvoice(invoice2, []).value;

  const r1 = createCreditNote(issued1, { amount: 5000, reason: 'Discount', date: '2025-10-08' }, []);
  assert.equal(r1.ok, true);
  assert.equal(r1.value.number, 'CN-2025-0001');

  const r2 = createCreditNote(issued2, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, [r1.value.number]);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'CN-2026-0001');
});

test('createCreditNote pads counter to 4 digits', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const existing = ['CN-2026-0999'];
  const r = createCreditNote(issued, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, existing);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-1000');
});

test('createCreditNote rejects invalid date format', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const r = createCreditNote(issued, { amount: 5000, reason: 'Discount', date: '10/08/2026' }, []);
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createCreditNote preserves invoice and customer info', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, ['INV-2026-0001']).value;

  const r = createCreditNote(issued, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.invoiceNumber, 'INV-2026-0001');
  assert.equal(r.value.customerId, 'C-001');
});

test('createCreditNote with various reasons', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const reasons = [
    'Customer Complaint',
    'Bulk Discount',
    'Early Payment Discount',
    'Quality Issue',
  ];

  for (const reason of reasons) {
    const r = createCreditNote(issued, { amount: 1000, reason, date: '2026-10-08' }, []);
    assert.equal(r.ok, true);
    assert.equal(r.value.reason, reason);
  }
});

test('createCreditNote handles null invoice', () => {
  const r = createCreditNote(null, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.deepEqual(r, { ok: false, error: 'NOT_ISSUED' });
});

test('createCreditNote returns credit note with all required fields', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const r = createCreditNote(issued, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(r.ok, true);
  assert(r.value.number);
  assert(r.value.invoiceNumber);
  assert(r.value.customerId);
  assert(r.value.amount);
  assert(r.value.reason);
  assert(r.value.date);
});

test('createCreditNote with large amount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const total = invoiceTotals(issued).value.total;

  const r = createCreditNote(issued, { amount: total, reason: 'Full Refund', date: '2026-10-08' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.amount, total);
});

test('createCreditNote for multiple invoices same customer', () => {
  const invoice1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(invoice1, []).value;

  const invoice2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const issued2 = issueInvoice(invoice2, []).value;

  const r1 = createCreditNote(issued1, { amount: 5000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(r1.ok, true);
  assert.equal(r1.value.invoiceNumber, issued1.number);

  const r2 = createCreditNote(issued2, { amount: 3000, reason: 'Discount', date: '2026-10-09' }, [r1.value.number]);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.invoiceNumber, issued2.number);
  assert.equal(r2.value.number, 'CN-2026-0002');
});

